WHERE a.delete_yn = 'N'


          AND a.bbs_master_id IN

              #{id}



          AND a.bbs_master_id = #{search.bbsMasterId}




  AND a.status = #{search.status}


  AND a.category_id = #{search.categoryId}




      AND a.title LIKE CONCAT('%', #{search.keyword}, '%')


      AND a.writer_name LIKE CONCAT('%', #{search.keyword}, '%')


      AND a.content LIKE CONCAT('%', #{search.keyword}, '%')


      AND (a.title LIKE CONCAT('%', #{search.keyword}, '%')
        OR a.writer_name LIKE CONCAT('%', #{search.keyword}, '%'))

mapper.update:
UPDATE tb_bbs_article
   SET comment_count = (
         SELECT COUNT(1) FROM tb_bbs_comment
          WHERE article_id = #{articleId}
            AND delete_yn  = 'N'
            AND status     = 'PUBLISHED'
       )
 WHERE article_id = #{articleId}
   AND delete_yn  = 'N'

UPDATE tb_bbs_article
   SET like_count = #{likeCount}
 WHERE article_id = #{articleId}
   AND delete_yn  = 'N'

UPDATE tb_bbs_article
   SET report_count = #{reportCount}
 WHERE article_id = #{articleId}
   AND delete_yn  = 'N'

mapper.delete:
DELETE FROM tb_bbs_article
 WHERE delete_yn = 'Y'
   AND updated_at <= #{cutoff}
